<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cat FAQ - All About Our Feline Friends</title>
    <style>
        :root {
            --color-bg: #121212;
            --color-surface: #1e1e1e;
            --color-primary: #bb86fc;
            --color-text: #e0e0e0;
            --color-muted-text: #b0b0b0;
            --color-focus: #03dac6;
            --color-border: #333333;
            --spacing-sm: 8px;
            --spacing-md: 16px;
            --spacing-lg: 24px;
            --radius: 8px;
        }

        body {
            background-color: var(--color-bg);
            color: var(--color-text);
            font-family: system-ui, -apple-system, sans-serif;
            line-height: 1.5;
            margin: 0;
            padding: var(--spacing-lg);
            display: flex;
            justify-content: center;
        }

        #root {
            width: 100%;
            max-width: 600px;
        }

        header {
            text-align: center;
            margin-bottom: var(--spacing-lg);
        }

        h1 {
            font-size: 2.5rem;
            color: var(--color-primary);
            margin-bottom: var(--spacing-sm);
        }

        header p {
            color: var(--color-muted-text);
            font-size: 1.1rem;
        }

        h2 {
            margin: 0;
            font-size: 1.1rem;
        }

        .example {
            background-color: var(--color-surface);
            border: 1px solid var(--color-border);
            border-radius: var(--radius);
            margin-bottom: var(--spacing-md);
            overflow: hidden;
            transition: transform 0.1s ease, box-shadow 0.2s ease;
        }

        .example:focus-within {
            border-color: var(--color-primary);
        }

        .disclosure-trigger {
            width: 100%;
            text-align: left;
            background: none;
            border: none;
            color: inherit;
            font: inherit;
            font-weight: 600;
            padding: var(--spacing-md);
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .disclosure-trigger:focus-visible {
            outline: 2px solid var(--color-focus);
            outline-offset: -2px;
        }

        /* Fallback for forced colors */
        @media (forced-colors: active) {
            .disclosure-trigger:focus-visible {
                outline: 2px solid ButtonBorder;
            }
            .example {
                border: 1px solid ButtonBorder;
            }
        }

        .disclosure-trigger .icon {
            width: 24px;
            height: 24px;
            transition: transform 0.2s ease;
            fill: var(--color-primary);
        }

        .disclosure-trigger[aria-expanded="true"] .icon {
            transform: rotate(180deg);
        }

        .details {
            padding: 0 var(--spacing-md) var(--spacing-md);
            color: var(--color-muted-text);
            border-top: 1px solid var(--color-border);
        }

        /* Skip link for accessibility */
        .skip-link {
            position: absolute;
            left: -10000px;
            top: auto;
            width: 1px;
            height: 1px;
            overflow: hidden;
        }

        .skip-link:focus {
            position: static;
            width: auto;
            height: auto;
            background: var(--color-primary);
            color: var(--color-bg);
            padding: var(--spacing-sm);
            text-decoration: none;
            z-index: 100;
        }
    </style>
    <!-- Load React and Babel for a "React-style" structure as requested -->
    <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
</head>
<body>
    <a href="#maincontent" class="skip-link">Skip to main content</a>
    <div id="root"></div>

    <script type="text/babel">
        const { useState } = React;

        const ChevronIcon = () => (
            <svg className="icon" viewBox="0 0 24 24" aria-hidden="true" width="24" height="24">
                <path d="M7 10l5 5 5-5z" />
            </svg>
        );

        const FAQItem = ({ question, answer, id }) => {
            const [isOpen, setIsOpen] = useState(false);
            const contentId = `content-${id}`;

            const handleKeyDown = (e) => {
                if (e.key === 'Escape' && isOpen) {
                    setIsOpen(false);
                }
            };

            return (
                <div className="example">
                    <h2>
                        <button
                            type="button"
                            className="disclosure-trigger"
                            aria-expanded={isOpen}
                            aria-controls={contentId}
                            onClick={() => setIsOpen(!isOpen)}
                            onKeyDown={handleKeyDown}
                        >
                            <span>{question}</span>
                            <ChevronIcon />
                        </button>
                    </h2>
                    <div 
                        className="details" 
                        id={contentId}
                        hidden={!isOpen}
                        onKeyDown={handleKeyDown}
                    >
                        <p>{answer}</p>
                    </div>
                </div>
            );
        };

        const App = () => {
            const faqData = [
                {
                    question: "Why do cats purr?",
                    answer: "Cats purr for many reasons, including contentment, stress relief, and to communicate with their kittens. Interestingly, the frequency of a cat's purr (between 25 and 150 Hertz) can actually help improve bone density and promote healing."
                },
                {
                    question: "Why do cats have whiskers?",
                    answer: "Whiskers are highly sensitive tactile organs that help cats navigate in the dark, judge the width of openings, and detect changes in air currents. They are deeply embedded in the body and connected to the cat's nervous system."
                },
                {
                    question: "How long do cats sleep?",
                    answer: "On average, cats sleep between 12 and 16 hours a day. This is an evolutionary trait from their ancestors who needed to conserve energy for intense bursts of hunting. Some cats can even sleep up to 20 hours a day!"
                },
                {
                    question: "Why do cats always land on their feet?",
                    answer: "Cats have a 'righting reflex' that allows them to reorient their bodies during a fall. Their flexible spines and lack of a functional collarbone help them twist their front and back halves independently to ensure they land paws-down."
                },
                {
                    question: "Why do cats like boxes?",
                    answer: "Boxes provide cats with a sense of security and a safe place to hide from predators while they stalk prey. They also help keep cats warm, as the cardboard acts as an insulator, and provide a cozy environment for sleeping."
                }
            ];

            return (
                <main id="maincontent" tabIndex="-1">
                    <header>
                        <h1>Cat FAQ</h1>
                        <p>Everything you ever wanted to know about cats!</p>
                    </header>
                    <section aria-label="Questions and Answers">
                        {faqData.map((item, index) => (
                            <FAQItem key={index} id={index} question={item.question} answer={item.answer} />
                        ))}
                    </section>
                </main>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
